from PIL import Image
import numpy as np
im=np.array(Image.open('/app/target.png').convert('RGB')).mean(2)<128

def runs(v):
 a=np.flatnonzero(im[v]); groups=[]
 for x in a:
  if not groups or x>groups[-1][-1]+1: groups.append([int(x)])
  else: groups[-1].append(int(x))
 return [(g[0],g[-1]) for g in groups]
def cruns(u):
 a=np.flatnonzero(im[:,u]); groups=[]
 for y in a:
  if not groups or y>groups[-1][-1]+1: groups.append([int(y)])
  else: groups[-1].append(int(y))
 return [(g[0],g[-1]) for g in groups]
print('row slices')
for y in range(350,681,15): print(y,runs(y))
print('column slices')
for x in range(320,726,20): print(x,cruns(x))
